import{$,status,download,canvasBlob}from'./common.js';
const snippet=`const makeSomething = (idea) => {\n  const curiosity = true;\n  const craft = "a little every day";\n\n  return {\n    ...idea,\n    curiosity,\n    craft,\n    ready: true,\n  };\n};`;
const canvas=$('#canvas');const themes={violet:['#d2b9fb','#8e96e9'],mint:['#bce9db','#72b6b6'],sunset:['#f3b887','#da829b'],slate:['#8493a8','#38475f']};
function render(){const code=$('#code').value,lines=code.split('\n');if(lines.length>80||code.length>16000){status('Keep the snippet under 80 lines and 16,000 characters.',true);$('#export').disabled=true;return}$('#export').disabled=false;const size=+$('#fontSize').value,padding=+$('#padding').value,lineHeight=size*1.65;const measure=document.createElement('canvas').getContext('2d');measure.font=size+'px monospace';const maxWidth=Math.max(...lines.map(l=>measure.measureText(l.replace(/\t/g,'  ')).width),260);const width=Math.min(1800,Math.ceil(maxWidth+padding*2+90)),height=Math.ceil(lines.length*lineHeight+padding*2+68);canvas.width=width*2;canvas.height=height*2;const g=canvas.getContext('2d');g.scale(2,2);const gradient=g.createLinearGradient(0,0,width,height);const colors=themes[$('#background').value];gradient.addColorStop(0,colors[0]);gradient.addColorStop(1,colors[1]);g.fillStyle=gradient;g.fillRect(0,0,width,height);g.shadowColor='#0004';g.shadowBlur=25;g.shadowOffsetY=12;g.fillStyle='#171925';g.beginPath();g.roundRect(padding,padding,width-padding*2,height-padding*2,13);g.fill();g.shadowColor='transparent';['#f46b67','#eebc4d','#62c582'].forEach((color,i)=>{g.fillStyle=color;g.beginPath();g.arc(padding+20+i*18,padding+23,5,0,Math.PI*2);g.fill()});g.fillStyle='#a4a7bb';g.font='11px monospace';g.textAlign='center';g.fillText($('#filename').value.slice(0,80),width/2,padding+27);g.textAlign='left';g.font=size+'px monospace';lines.forEach((line,i)=>{let x=padding+20;const y=padding+65+i*lineHeight;if($('#numbers').checked){g.fillStyle='#656a82';g.fillText(String(i+1).padStart(2,' '),x,y);x+=size*2.7}const tokens=line.replace(/\t/g,'  ').match(/("[^"\n]*"|'[^'\n]*'|\/\/.*$|\b(?:const|let|var|return|function|import|from|def|class|if|else|True|False|true|false|None|null)\b|\b\d+\b|[^"'\s]+|\s+)/g)||[''];for(const token of tokens){g.fillStyle=$('#language').value==='Plain text'?'#e3e6f3':/^\/\//.test(token)?'#737e9a':/^["']/.test(token)?'#b7d892':/^(const|let|var|return|function|import|from|def|class|if|else)$/.test(token)?'#c3a0f3':/^(true|false|True|False|null|None|\d+)$/.test(token)?'#eeaa86':'#dfe4f5';g.fillText(token,x,y);x+=g.measureText(token).width}});$('#paddingValue').textContent=padding+' px';status(width+' × '+height+' logical pixels · '+canvas.width+' × '+canvas.height+' export')}
for(const id of ['code','background','padding','fontSize','filename','numbers','language'])$('#'+id).oninput=render;$('#sample').onclick=()=>{$('#code').value=snippet;render()};$('#export').onclick=async()=>{try{download(await canvasBlob(canvas),'code-canvas.png');status('Your snippet is ready to share.')}catch(e){status(e.message,true)}};$('#code').value=snippet;render();
